            "text": "Making [[steel]] is hot, heavy, and dangerous work, so factories now use robots to help. These machines work close to metal burning with extreme heat, where no person could safely stand. They [[dump]] unwanted materials from the mixture and [[rub]] the cooling metal smooth. Some even add [[fancy]] finishing to fine parts. A robot can also feel the smallest [[bump]] that marks a hidden fault.",
            "ko": "강철을 만드는 일은 뜨겁고 고되고 위험해서, 오늘날 공장들은 로봇의 도움을 받는다. 이 기계들은 사람이라면 안전하게 서 있을 수 없는, 극심한 열로 타오르는 금속 곁에서 일한다. 그것들은 혼합물에서 필요 없는 물질을 쏟아 내고 식어 가는 금속을 문질러 매끈하게 다듬는다. 어떤 로봇은 정교한 부품에 공들인 마무리까지 더한다. 로봇은 또 숨은 결함을 알려 주는 아주 작은 돌기까지 감지해 낼 수 있다.",
