        "title": "Building Stronger Muscles",
        "titleKo": "더 튼튼한 근육 만들기",
        "genre": "에세이",
        "tiers": {
          "1": {
            "text": "Training to grow stronger takes time and care. At first, lifting heavy weights may make your body hurt, and you might hear the [[odd]] sound of someone [[dragging:drag]] a machine across the room. Do not [[spoil]] your progress by rushing; growth comes slowly. Treat rest as a kind of [[seal]] that locks in each day's effort. Some [[shame]] after a missed workout is normal, but never let it stop you.",
            "ko": "더 강해지기 위해 훈련하는 데에는 시간과 주의가 필요하다. 처음에는 무거운 역기를 들면 몸이 아플 수 있고, 누군가 운동 기구를 방 저편으로 끌고 가는 묘한 소리를 들을지도 모른다. 서두르다가 진전을 본 것을 망치지 마라. 성장은 천천히 찾아온다. 휴식을 그날그날의 노력을 단단히 가두어 두는 일종의 봉인으로 여기라. 운동을 빼먹은 뒤 어느 정도 부끄러움을 느끼는 것은 당연하지만, 그것 때문에 결코 멈추지는 마라.",
            "glossary": [
              {
                "en": "take time and care",
                "ko": "시간과 주의가 필요하다"
              },
              {
                "en": "lift heavy weights",
                "ko": "무거운 중량을 들다"
              },
              {
                "en": "across the room",
                "ko": "방 저편으로"
              },
              {
                "en": "lock in",
                "ko": "단단히 가두어 두다"
              }
            ]
          },
          "2": {
            "text": "Training to grow stronger takes time and care. At first, lifting heavy weights may make your arms hurt, and you might hear the [[odd]] sound of someone [[dragging:drag]] a machine across the room. Do not [[spoil]] your progress by rushing; growth comes slowly. Treat rest as a kind of [[seal]] that locks in each day's effort. A little [[shame]] after a missed workout is normal, but never let it stop you. Eat well, sleep deeply, and your body will thank you for your patient work.",
            "ko": "더 강해지기 위해 훈련하는 데에는 시간과 주의가 필요하다. 처음에는 무거운 역기를 들면 팔이 아플 수 있고, 누군가 운동 기구를 방 저편으로 끌고 가는 묘한 소리를 들을지도 모른다. 서두르다가 진전을 본 것을 망치지 마라. 성장은 천천히 찾아온다. 휴식을 그날그날의 노력을 단단히 가두어 두는 일종의 봉인으로 여기라. 운동을 빼먹은 뒤 조금 부끄러운 마음이 드는 것은 당연하지만, 그것 때문에 절대 멈추지는 마라. 잘 먹고 푹 자라. 그러면 몸이 그동안의 꾸준한 노력에 고마워할 것이다.",
            "glossary": [
              {
                "en": "missed workout",
                "ko": "빼먹은 운동"
              },
              {
                "en": "never let it stop you",
                "ko": "그것 때문에 결코 멈추지 마라"
              },
              {
                "en": "sleep deeply",
                "ko": "푹 자다"
              },
              {
                "en": "thank A for B",
                "ko": "B에 대해 A에게 고마워하다"
              }
            ]
          },
          "3": {
            "text": "Training to grow stronger takes much time and care. At first, lifting heavy weights may make your tired arms feel sore for days, and you might hear the [[odd]] sound of someone [[dragging:drag]] a heavy machine across the room. Do not [[spoil]] your hard-won progress by rushing; real growth comes slowly over many months. Treat proper rest as a kind of [[seal]] that locks in each day's honest effort. A little [[shame]] after a missed workout is normal, but you must never let it stop you. Eat well, sleep deeply, and your body will thank you for your patient work.",
            "ko": "더 강해지기 위해 훈련하는 데에는 많은 시간과 주의가 필요하다. 처음에는 무거운 역기를 들면 지친 팔이 며칠 동안 욱신거릴 수 있고, 누군가 무거운 운동 기구를 방 저편으로 끌고 가는 묘한 소리를 들을지도 모른다. 서두르다가 힘들게 얻은, 진전을 본 것을 망치지 마라. 진정한 성장은 여러 달에 걸쳐 천천히 찾아온다. 적절한 휴식을 그날그날의 성실한 노력을 단단히 가두어 두는 일종의 봉인으로 여기라. 운동을 빼먹은 뒤 조금 부끄러운 마음이 드는 것은 당연하지만, 그것 때문에 결코 멈춰서는 안 된다. 잘 먹고 푹 자라. 그러면 몸이 그동안의 꾸준한 노력에 고마워할 것이다.",
            "glossary": [
              {
                "en": "feel sore",
                "ko": "욱신거리다, 쑤시다"
              },
              {
                "en": "hard-won",
                "ko": "힘들게 얻은"
              },
              {
                "en": "over many months",
                "ko": "여러 달에 걸쳐"
              },
              {
                "en": "proper rest",
                "ko": "적절한 휴식"
              }
            ]
          }
        }
